#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells = 0;
    for(int i=0;i<n;i++){
        cin >> ksz[i];
        raw[i].resize(ksz[i]);
        for(int j=0;j<ksz[i];j++) cin >> raw[i][j].first >> raw[i][j].second;
        totalCells += ksz[i];
    }

    // Generate all distinct orientations for piece i
    // Orientation: flip f (0 or 1), then rotate r times 90° CCW
    // Transform: if f=1, reflect x -> -x, then rotate r times: (x,y)->(−y,x)
    struct Orient {
        vector<pair<int,int>> cells;
        int w, h, r, f;
    };

    vector<vector<Orient>> orients(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++){
            for(int r=0;r<4;r++){
                vector<pair<int,int>> tr;
                for(auto [x,y]:raw[i]){
                    int tx=x, ty=y;
                    if(f) tx=-tx;
                    for(int rr=0;rr<r;rr++){int nx=-ty,ny=tx;tx=nx;ty=ny;}
                    tr.push_back({tx,ty});
                }
                int mx=INT_MAX, my=INT_MAX;
                for(auto [x,y]:tr){mx=min(mx,x);my=min(my,y);}
                for(auto&[x,y]:tr){x-=mx;y-=my;}
                sort(tr.begin(),tr.end());
                if(seen.insert(tr).second){
                    int mxx=0,myy=0;
                    for(auto [x,y]:tr){mxx=max(mxx,x);myy=max(myy,y);}
                    orients[i].push_back({tr,mxx+1,myy+1,r,f});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){return ksz[a]>ksz[b];});

    int bestArea=INT_MAX, bestW=0, bestH=0;
    vector<int> bx(n),by(n),br(n),bf(n);

    auto tryW=[&](int W)->bool{
        int Hmax=min(totalCells+n*10+20, bestArea/W);
        if(Hmax<1)return false;
        if((long long)W*Hmax>4000000LL) Hmax=4000000/W;
        if(Hmax<1)return false;

        vector<int> skyline(W,0);
        vector<vector<bool>> grid(W, vector<bool>(Hmax,false));
        vector<int> px(n),py(n),pr(n),pf(n);
        int curH=0;

        for(int idx=0;idx<n;idx++){
            int i=order[idx];
            int bs=INT_MAX; int bxx=-1,byy=-1,boi=-1;
            for(int oi=0;oi<(int)orients[i].size();oi++){
                auto&o=orients[i][oi];
                if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){
                    int sy=0;
                    for(auto [cx,cy]:o.cells) sy=max(sy, skyline[x+cx]-cy);
                    if(sy<0)sy=0;
                    for(int y=sy;y+o.h<=Hmax;y++){
                        bool ok=true;
                        for(auto [cx,cy]:o.cells) if(grid[x+cx][y+cy]){ok=false;break;}
                        if(ok){
                            int nh=max(curH,y+o.h);
                            if((long long)W*nh>=bestArea)break;
                            int sc=nh*10000+y*100+x;
                            if(sc<bs){bs=sc;bxx=x;byy=y;boi=oi;}
                            break;
                        }
                    }
                }
            }
            if(boi<0)return false;
            auto&o=orients[i][boi];
            px[i]=bxx;py[i]=byy;pr[i]=o.r;pf[i]=o.f;
            for(auto [cx,cy]:o.cells){
                grid[bxx+cx][byy+cy]=true;
                skyline[bxx+cx]=max(skyline[bxx+cx],byy+cy+1);
                curH=max(curH,byy+cy+1);
            }
        }
        int area=W*curH;
        if(area<bestArea){bestArea=area;bestW=W;bestH=curH;bx=px;by=py;br=pr;bf=pf;return true;}
        return false;
    };

    auto t0=chrono::steady_clock::now();
    int sq=(int)ceil(sqrt((double)totalCells));
    vector<int> ws;
    for(int w=max(1,sq/3);w<=min(totalCells*2,sq*4);w++) ws.push_back(w);
    sort(ws.begin(),ws.end(),[&](int a,int b){return abs(a-sq)<abs(b-sq);});

    for(int w:ws){
        if(chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now()-t0).count()>8000)break;
        tryW(w);
    }

    if(bestArea==INT_MAX){
        // fallback: place pieces in a row
        int W=0;
        for(int i=0;i<n;i++) W+=orients[i][0].w;
        int H=0;
        for(int i=0;i<n;i++) H=max(H,orients[i][0].h);
        bestW=W;bestH=H;
        int cx=0;
        for(int i=0;i<n;i++){
            bx[i]=cx;by[i]=0;br[i]=orients[i][0].r;bf[i]=orients[i][0].f;
            cx+=orients[i][0].w;
        }
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bx[i]<<" "<<by[i]<<" "<<br[i]<<" "<<bf[i]<<"\n";
}
